from networkx import Graph, girth
import networkx as nx

g = nx.Graph()
for i in range(23):
    g.add_node(i)

# Add edges to the graph such that every vertex has degree between 3 and 4
for i in range(23):
    for j in range(i+1, 23):
        if len(list(g.neighbors(i))) < 4 and len(list(g.neighbors(j))) < 4:
            g.add_edge(i, j)

# Check if the girth of the graph is at least 7
if girth(g) >= 7:
    print("SATISFIABLE")
    print(list(g.edges))
else:
    print("UNSATISFIABLE")
